#ifdef CHECK
#undef CHECK
#endif
#define CHECK(x) do{if(!(x)){std::cerr<<"CHECK failed line "<<__LINE__<<": "<<#x<<'\n';std::exit(1);}}while(0)
static CurrentBinding current(const std::shared_ptr<const Source>&s){CurrentBinding c;c.source=s->binding();c.sourceOwner=c.source.sourceOwner;c.fullTargetOwner=s->target().owner;c.sourceBitmap=s->target().w[8];return c;}
static TileObservation tileFor(const Source&s,unsigned n){
 TileObservation t;uint32_t descriptorBase=0;for(uint32_t a:{0x20000000u,0x40000000u,0x80000000u})if(!overlap(a,300*64,s.target().w[8],614416)){descriptorBase=a;break;}CHECK(descriptorBase);
 uint32_t payload=0;for(uint32_t a:{0xc0000000u,0xd0000000u,0xe0000000u})if(!overlap(a,2048,s.target().w[8],614416)){payload=a;break;}CHECK(payload);
 t.descriptorGuest=t.expectedSlotDescriptor=descriptorBase+64*n;t.payloadGuest=payload;t.before={{3,3,3,11,0,0x01000000u+2048*n,3}};t.after=t.before;t.after[4]=t.payloadGuest;t.originalUploadReturned=true;
 unsigned x=(n/15)*32,y=(n%15)*32;for(unsigned yy=0;yy<32;++yy)for(unsigned xx=0;xx<32;++xx){uint16_t p=to1555(s.original()[(y+yy)*640+x+xx]);unsigned at=2*(yy*32+xx);t.pixels[at]=uint8_t(p);t.pixels[at+1]=uint8_t(p>>8);}return t;
}
static void complete(Witness&w,const std::shared_ptr<const Source>&s,const CurrentBinding&c,const Plane&p,std::atomic<uint64_t>&events){CHECK(w.begin(s,c,p,events.load(),events));for(unsigned k=0;k<300;++k)CHECK(w.tile(tileFor(*s,k),c));CHECK(w.uploaded()==300);CHECK(w.finish(p,true,c));}
static void positives(){for(unsigned player=1;player<=2;++player)for(unsigned mode=0;mode<=2;++mode){auto f=std::unique_ptr<player_scene_fixture::Fixture>(new player_scene_fixture::Fixture(player,mode));CHECK(f->source);auto c=current(f->source);std::atomic<uint64_t>events{19};Witness w;complete(w,f->source,c,f->actualUpload,events);auto proof=w.proofForPresentation(c,f->actualUpload);CHECK(proof&&proof->current(c)&&proof->uploadEvent(c)==19);CHECK(proof->source(c)==f->source);std::array<uint32_t,300>keys{};CHECK(proof->keys(c,keys));for(unsigned k=0;k<300;++k)CHECK(keys[k]==tileFor(*f->source,k).after[5]);auto prepared=std::unique_ptr<nfs_player_scene_cpu::Prepared>(new nfs_player_scene_cpu::Prepared);CHECK(proof->preparedForPresentation(c,f->actualUpload,*prepared));CHECK(prepared->valid&&prepared->original==f->source->original()&&prepared->keys==keys);w.reset();CHECK(!proof->current(c)&&!proof->source(c));CHECK(!proof->keys(c,keys));for(auto k:keys)CHECK(!k);CHECK(!proof->preparedForPresentation(c,f->actualUpload,*prepared)&&!prepared->valid);}}
static void bindingNegatives(player_scene_fixture::Fixture&f){auto s=f.source;auto good=current(s);std::atomic<uint64_t>events{7};std::vector<std::function<void(CurrentBinding&)>>mutations={
 [](CurrentBinding&c){++c.source.form;},[](CurrentBinding&c){++c.source.formGuest;},[](CurrentBinding&c){++c.source.sourceOwner;},[](CurrentBinding&c){++c.source.archive;},[](CurrentBinding&c){++c.source.gameOwner;},[](CurrentBinding&c){++c.source.thread;},[](CurrentBinding&c){++c.source.epoch;},[](CurrentBinding&c){++c.source.lifetime;},[](CurrentBinding&c){++c.source.generation;},[](CurrentBinding&c){++c.source.contentSerial;},[](CurrentBinding&c){++c.source.copySerial;},[](CurrentBinding&c){c.source.kind=c.source.kind==nfs_player_scene_cpu::SourceKind::Initial?nfs_player_scene_cpu::SourceKind::Refresh:nfs_player_scene_cpu::SourceKind::Initial;},[](CurrentBinding&c){++c.sourceOwner;},[](CurrentBinding&c){++c.fullTargetOwner;},[](CurrentBinding&c){++c.sourceBitmap;}};
 for(const auto&mutate:mutations){auto bad=good;mutate(bad);Witness w;CHECK(!w.begin(s,bad,f.actualUpload,7,events));CHECK(w.begin(s,good,f.actualUpload,7,events));CHECK(!w.tile(tileFor(*s,0),bad));complete(w,s,good,f.actualUpload,events);auto proof=w.proofForPresentation(good,f.actualUpload);CHECK(proof&&!proof->current(bad)&&!proof->source(bad));std::array<uint32_t,300>keys{};CHECK(!proof->keys(bad,keys));CHECK(!w.proofForPresentation(bad,f.actualUpload));CHECK(!proof->current(good));}
 Witness empty;CHECK(!empty.begin({},good,f.actualUpload,7,events));
}
static void planeAndLifetimeNegatives(player_scene_fixture::Fixture&f){auto s=f.source;auto c=current(s);std::atomic<uint64_t>events{13};auto p=std::unique_ptr<Plane>(new Plane(f.actualUpload));Witness w;
 for(unsigned k=0;k<4;++k){*p=f.actualUpload;if(k==0)p->valid=0;if(k==1)--p->width;if(k==2)++p->target.owner;if(k==3)p->pixels[234567]^=1;CHECK(!w.begin(s,c,*p,13,events));CHECK(w.begin(s,c,f.actualUpload,13,events));for(unsigned j=0;j<300;++j)CHECK(w.tile(tileFor(*s,j),c));CHECK(!w.finish(*p,true,c));}
 CHECK(w.begin(s,c,f.actualUpload,13,events));for(unsigned j=0;j<299;++j)CHECK(w.tile(tileFor(*s,j),c));CHECK(!w.finish(f.actualUpload,true,c));complete(w,s,c,f.actualUpload,events);CHECK(!w.tile(tileFor(*s,0),c));
 CHECK(w.begin(s,c,f.actualUpload,13,events));for(unsigned j=0;j<300;++j)CHECK(w.tile(tileFor(*s,j),c));CHECK(!w.finish(f.actualUpload,false,c));CHECK(w.begin(s,c,f.actualUpload,13,events));for(unsigned j=0;j<300;++j)CHECK(w.tile(tileFor(*s,j),c));CHECK(!w.finish(f.actualUpload,true,c,true));
 for(uint32_t retired:{c.sourceOwner,c.fullTargetOwner,c.sourceBitmap}){complete(w,s,c,f.actualUpload,events);auto proof=w.proofForPresentation(c,f.actualUpload);CHECK(proof);w.retire(retired);CHECK(!proof->current(c));}
 complete(w,s,c,f.actualUpload,events);auto proof=w.proofForPresentation(c,f.actualUpload);CHECK(proof);w.slot1Overwrite();CHECK(!proof->current(c));
 std::shared_ptr<const Proof>escaped;{Witness local;complete(local,s,c,f.actualUpload,events);escaped=local.proofForPresentation(c,f.actualUpload);CHECK(escaped);}CHECK(!escaped->current(c));
}
static void eventNegatives(player_scene_fixture::Fixture&f){auto s=f.source;auto c=current(s);std::atomic<uint64_t>events{27};Witness w;CHECK(!w.begin(s,c,f.actualUpload,0,events));CHECK(!w.begin(s,c,f.actualUpload,26,events));events.store(UINT64_MAX);CHECK(!w.begin(s,c,f.actualUpload,UINT64_MAX,events));events.store(27);
 CHECK(w.begin(s,c,f.actualUpload,27,events));events.fetch_add(1);CHECK(!w.tile(tileFor(*s,0),c));CHECK(w.begin(s,c,f.actualUpload,28,events));for(unsigned k=0;k<300;++k)CHECK(w.tile(tileFor(*s,k),c));events.fetch_add(1);CHECK(!w.finish(f.actualUpload,true,c));complete(w,s,c,f.actualUpload,events);auto proof=w.proofForPresentation(c,f.actualUpload);CHECK(proof);events.fetch_add(1);CHECK(!proof->current(c)&&!proof->source(c)&&!proof->uploadEvent(c));std::array<uint32_t,300>keys{};CHECK(!proof->keys(c,keys));CHECK(!w.proofForPresentation(c,f.actualUpload));}
static void descriptorAndPayloadNegatives(player_scene_fixture::Fixture&f){auto s=f.source;auto c=current(s);std::atomic<uint64_t>events{3};Witness w;std::vector<std::function<void(TileObservation&)>>bad={
 [](TileObservation&t){t.originalUploadReturned=false;},[](TileObservation&t){t.descriptorGuest=0;},[](TileObservation&t){++t.expectedSlotDescriptor;},[](TileObservation&t){t.payloadGuest=0;},[](TileObservation&t){t.tableGuest=1;},[](TileObservation&t){t.before[0]=t.after[0]=2;},[](TileObservation&t){t.before[1]=t.after[1]=2;},[](TileObservation&t){t.before[2]=t.after[2]=2;},[](TileObservation&t){t.before[3]=t.after[3]=10;},[](TileObservation&t){t.before[6]=t.after[6]=2;},[](TileObservation&t){++t.after[4];},[](TileObservation&t){++t.after[5];},[](TileObservation&t){t.payloadGuest=t.descriptorGuest;t.after[4]=t.payloadGuest;},[](TileObservation&t){t.before[5]=t.after[5]=UINT32_MAX-1023;},[](TileObservation&t){t.descriptorGuest=t.expectedSlotDescriptor=UINT32_MAX-10;},[](TileObservation&t){t.payloadGuest=UINT32_MAX-1023;t.after[4]=t.payloadGuest;},[&](TileObservation&t){t.descriptorGuest=t.expectedSlotDescriptor=c.sourceBitmap;},[&](TileObservation&t){t.payloadGuest=c.sourceBitmap+16;t.after[4]=t.payloadGuest;}};
 for(auto mutate:bad){auto t=tileFor(*s,0);mutate(t);CHECK(w.begin(s,c,f.actualUpload,3,events));CHECK(!w.tile(t,c));}
 for(unsigned k=0;k<7;++k)if(k!=4){auto t=tileFor(*s,0);t.after[k]^=1;CHECK(w.begin(s,c,f.actualUpload,3,events));CHECK(!w.tile(t,c));}
 for(unsigned which=0;which<3;++which){CHECK(w.begin(s,c,f.actualUpload,3,events));auto a=tileFor(*s,0),b=tileFor(*s,1);CHECK(w.tile(a,c));if(which==0)b.descriptorGuest=b.expectedSlotDescriptor=a.descriptorGuest;else if(which==1)b.descriptorGuest=b.expectedSlotDescriptor=a.descriptorGuest+4;else b.before[5]=b.after[5]=a.after[5]+1024;CHECK(!w.tile(b,c));}
 // Touch every tile's final payload byte: no prefix/subset proof can succeed.
 for(unsigned badTile=0;badTile<300;++badTile){CHECK(w.begin(s,c,f.actualUpload,3,events));for(unsigned k=0;k<badTile;++k)CHECK(w.tile(tileFor(*s,k),c));auto t=tileFor(*s,badTile);t.pixels[2047]^=1;CHECK(!w.tile(t,c));}
}
int main(){positives();auto f=std::unique_ptr<player_scene_fixture::Fixture>(new player_scene_fixture::Fixture(1,1));CHECK(f->source);bindingNegatives(*f);planeAndLifetimeNegatives(*f);eventNegatives(*f);descriptorAndPayloadNegatives(*f);std::cout<<"Player native upload witness: PASS (CPU sealed-source/upload identity only)\n";}
